"use strict"

// Unused loader call.
require("../../../")

// An uncaught error can cause Node to dump the enormous single-line loader
// source and truncate the error code at the end of piped stderr. Report the
// caught error code directly so CI can distinguish rejection from a crash.
try {
  require("./main.mjs")
} catch (error) {
  const code = error && (error.code || error.name)
  process.stderr.write(`cli-hook-fail:${code}\n`)
  process.exitCode = 1
}
